/* Verify type T.  */

void
verify_type (const_tree t)
{
  bool error_found = false;
  tree mv = TYPE_MAIN_VARIANT (t);
  tree ct = TYPE_CANONICAL (t);

  if (OPAQUE_TYPE_P (t))
    {
      verify_opaque_type (t, mv, ct);
      return;
