      && !RECORD_OR_UNION_TYPE_P (TYPE_CANONICAL (t))
      && TREE_CODE (t) != ARRAY_TYPE
      && TYPE_MODE (t) != TYPE_MODE (TYPE_CANONICAL (t)))
